(function(){
  // The bytes are the measurement, so they are written here once and rendered
  // rather than restated in prose where the two copies could drift.
  var rows = [
    ["4:4:4", 1885, "chroma at luma resolution, what this ships by default"],
    ["4:2:2", 1699, "halved horizontally, what the camera shot"],
    ["4:2:0", 1585, "halved on both axes, what Instagram stores anyway"]
  ];
  var el = document.getElementById("ig-chroma");
  if (!el) return;
  var html = '<div class="row head"><span>chroma</span><span class="n">KB</span><span>what it is</span></div>';
  for (var i = 0; i < rows.length; i++) {
    html += '<div class="row"><span>' + rows[i][0] + '</span><span class="n">' +
            rows[i][1] + '</span><span>' + rows[i][2] + '</span></div>';
  }
  el.innerHTML = html;
})();
